// ===== Abschnitt 1: Konstanten =====
// Jede Kategorie legt Score-Bereich, Airtable-Priorität und Airtable-Status fest
const KATEGORIEN = {
  hot:  { min: 70, max: 100, prioritaet: 'Hoch',    status: 'Qualifiziert' },
  warm: { min: 40, max: 69,  prioritaet: 'Mittel',  status: 'Qualifiziert' },
  kalt: { min: 1,  max: 39,  prioritaet: 'Niedrig', status: 'Unqualifiziert' },
  spam: { min: 0,  max: 0,   prioritaet: 'Niedrig', status: 'Unqualifiziert' },
  // Zu knapp für eine Bewertung: der Lead bekommt eine Rückfrage-Mail
  rueckfrage: { min: 10, max: 39, prioritaet: 'Mittel', status: 'Rückfrage' },
};
// Unklare KI-Antwort wird vorsichtig als warm behandelt, damit kein Lead verloren geht
const FALLBACK_KATEGORIE = 'warm';

// ===== Abschnitt 2: KI-Ergebnis prüfen und für Airtable aufbereiten =====
return $input.all().map((item, index) => {
  const ki = item.json.output || {};
  // Lead-Daten holen: erst über die Zuordnung, sonst über denselben Index (1 Anfrage = 1 Lauf)
  let lead;
  try {
    lead = $('check_lead').itemMatching(index).json;
  } catch (e) {
    lead = $('check_lead').all()[index].json;
  }

  const kategorie = KATEGORIEN[ki.kategorie] ? ki.kategorie : FALLBACK_KATEGORIE;
  const regel = KATEGORIEN[kategorie];
  const rohScore = Math.round(Number(ki.score));
  // Score immer in den Bereich der Kategorie zwingen, damit beide zusammenpassen
  const score = Number.isFinite(rohScore) ? Math.min(regel.max, Math.max(regel.min, rohScore)) : regel.min;

  return {
    json: {
      // E-Mail-Absendernamen sind oft ungenau, dort nimmt die KI den Namen aus dem Text
      name: (lead.quelle === 'E-Mail' && ki.name) ? ki.name : lead.name,
      email: lead.email,
      telefon: lead.telefon || ki.telefon || '',
      unternehmen: lead.firma || ki.firma || '',
      datenschutz: lead.datenschutz === true,
      nachricht: lead.nachricht,
      datum: lead.datum,
      quelle: lead.quelle,
      // Auswahlfelder aus dem Formular (bei Mail-Leads leer)
      thema: lead.thema || '',
      zeitrahmen: lead.zeitrahmen || '',
      kategorie,
      score,
      prioritaet: regel.prioritaet,
      status: regel.status,
      kiReasoning: ki.begruendung || '',
      kiRecherche: ki.recherche || '',
      antwortEntwurf: ki.antwortEntwurf || '',
    },
    pairedItem: { item: index },
  };
});

// ===== Abschnitt 1: Konstanten =====
// Freemail-Anbieter: Absender ist eher eine Privatperson als eine Firma
const FREEMAIL_DOMAINS = ['gmail.com', 'googlemail.com', 'web.de', 'gmx.de', 'gmx.net', 't-online.de', 'outlook.com', 'outlook.de', 'hotmail.com', 'hotmail.de', 'yahoo.com', 'yahoo.de', 'icloud.com', 'freenet.de'];
// Nur fast leere Nachrichten gelten als Spam-Verdacht (kurze echte Anfragen wie "Brauche Hilfe" gehen zur KI)
const MIN_NACHRICHT_LAENGE = 3;
// Mehr Links in der Nachricht gelten als Spam-Verdacht
const MAX_LINKS = 3;
// Automatische Absender bekommen keine Antwort-Mail (verhindert Mail-Schleifen)
const AUTOMATISCHE_ABSENDER = /(no-?reply|do-?not-?reply|mailer-daemon|postmaster|newsletter)/i;

// ===== Abschnitt 2: Lead normalisieren und auf Spam-Verdacht prüfen =====
return $input.all().map((item, index) => {
  const lead = item.json;
  const email = String(lead.email || '').toLowerCase().trim();
  const domain = email.split('@')[1] || '';
  const nachricht = String(lead.nachricht || '').trim();
  const anzahlLinks = (nachricht.match(/https?:\/\//gi) || []).length;

  const gruende = [];
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) gruende.push('ungültige E-Mail-Adresse');
  if (AUTOMATISCHE_ABSENDER.test(email)) gruende.push('automatischer Absender');
  if (nachricht.length < MIN_NACHRICHT_LAENGE) gruende.push('Nachricht zu kurz');
  if (anzahlLinks > MAX_LINKS) gruende.push('zu viele Links');

  return {
    json: {
      ...lead,
      email,
      domain,
      istFreemail: FREEMAIL_DOMAINS.includes(domain),
      spamVerdacht: gruende.length > 0,
      spamGrund: gruende.length > 0 ? 'Vorfilter: ' + gruende.join(', ') : '',
    },
    pairedItem: { item: index },
  };
});

